    docs = ['{"a": [1, 2.5, -3e2, true, false, null], "b": {"c": "d"}}', '  [ ]  ', '"x"', '0', '-0.0',
            '"\\u00e9 \\ud83d\\ude00 \\n \\" \\\\ \\/"', '{"": {"": []}}', '1E+2', '[{"k": [[]]}]']
    for d in docs:
        assert parse_json(d) == json.loads(d), d
    assert type(parse_json("12")) is int and type(parse_json("1.0")) is float

